// ===== Match Kalshi Teams (v3 — three-way market model) =====
// Root cause of the "69% gap" bug: Kalshi lists a 3-way soccer market as
// THREE independent binary contracts (Home-yes, Draw-yes, Away-yes) that
// all share one title. The old code grabbed only ONE leg (whichever
// matched home_team) and mislabeled its yes/no as if they were two
// opposing teams' win probabilities. This version captures all three
// legs distinctly and reports each on its own, correctly labeled.

const items    = $input.all();
const awayTeam = $('Parse Teams').item.json.away_team || '';
const homeTeam = $('Parse Teams').item.json.home_team || '';

const normalize = s => (s || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[^a-z0-9 -]/g, ' ')
  .replace(/-/g, ' ').replace(/\s+/g, ' ').trim();

const SYNONYM_GROUPS = [
  ['bosnia', 'bosnia herzegovina', 'herzegovina'],
  ['cape verde', 'cabo verde', 'cape verde islands'],
  ['congo dr', 'dr congo', 'congo'],
  ['cote d ivoire', 'ivory coast', 'cote divoire'],
  ['korea republic', 'south korea'],
  ['ir iran', 'iran'],
  ['usa', 'united states'],
];

const findGroup = n => {
  if (!n) return null;
  for (const g of SYNONYM_GROUPS) {
    if (g.some(p => p === n || n.includes(p) || p.includes(n))) return g;
  }
  return null;
};

const STOP = ['the','and','for','with','city','team','state'];
const sigWords = n => n.split(' ').filter(w => w.length > 3 && !STOP.includes(w));

const titleMatchesTeam = (title, team) => {
  const ti = normalize(title), t = normalize(team);
  if (!t || !ti) return false;
  if (ti.includes(t)) return true;
  const g = findGroup(t);
  if (g && g.some(p => ti.includes(p))) return true;
  return sigWords(t).some(w => ti.includes(w));
};

const subMatchesTeam = (sub, team) => {
  const s = normalize(sub), t = normalize(team);
  if (!s || !t) return false;
  if (s.includes(t) || t.includes(s)) return true;
  const g = findGroup(t);
  if (g && g.some(p => s.includes(p))) return true;
  return sigWords(t).some(w => s.includes(w));
};

const isDrawLeg = subTitle => /\btie\b|\bdraw\b/i.test(subTitle || '');

let kalshiEdge = null;

try {
  const cacheRow = items[0]?.json;
  const markets  = cacheRow?.data?.markets;

  if (Array.isArray(markets) && markets.length > 0 && homeTeam && homeTeam !== 'General') {

    const gameMarkets = markets.filter(m =>
      titleMatchesTeam(m.title, awayTeam) && titleMatchesTeam(m.title, homeTeam)
    );

    if (gameMarkets.length > 0) {
      // Classify each leg: home-win, away-win, or draw — NOT yes/no of one leg
      const homeLeg = gameMarkets.find(m =>
        !isDrawLeg(m.yes_sub_title) && subMatchesTeam(m.yes_sub_title, homeTeam));
      const awayLeg = gameMarkets.find(m =>
        !isDrawLeg(m.yes_sub_title) && subMatchesTeam(m.yes_sub_title, awayTeam));
      const drawLeg = gameMarkets.find(m => isDrawLeg(m.yes_sub_title));

      const legPct = leg => {
        if (!leg) return null;
        const yd = leg.yes_bid_dollars ?? leg.last_price_dollars ?? null;
        return yd !== null ? (parseFloat(yd) * 100) : null;
      };
      const legVol = leg => leg ? parseFloat(leg.volume_fp ?? 0) : 0;

      const homePct = legPct(homeLeg), awayPct = legPct(awayLeg), drawPct = legPct(drawLeg);

      if (homePct !== null || awayPct !== null) {
        const totalVolume = legVol(homeLeg) + legVol(awayLeg) + legVol(drawLeg);
        kalshiEdge = {
          market:            gameMarkets[0].title,
          home_team:         homeTeam,
          away_team:         awayTeam,
          home_implied_pct:  homePct !== null ? homePct.toFixed(1) : 'n/a',
          away_implied_pct:  awayPct !== null ? awayPct.toFixed(1) : 'n/a',
          draw_implied_pct:  drawPct !== null ? drawPct.toFixed(1) : 'n/a',
          volume:            totalVolume.toFixed(0),
        };
      }
    }
  }
} catch(e) {}

return [{
  json: {
    ...(items[0]?.json || {}),
    kalshi_edge:      kalshiEdge,
    kalshi_available: kalshiEdge !== null,
  }
}];

const items = $input.all();
const away  = $('Parse Teams').item.json.away_team || '';
const home  = $('Parse Teams').item.json.home_team || '';

// Word-level team name matching (same logic as Match Kalshi Teams)
const matchesTeam = (name, team) => {
  if (!name || !team) return false;
  const n = name.toLowerCase();
  const t = team.toLowerCase();
  if (n.includes(t) || t.includes(n)) return true;
  const words = t.split(/\s+/).filter(w =>
    w.length > 3 &&
    !['the','and','for','with','city','team','state','fc','sc','united','sporting'].includes(w)
  );
  return words.some(w => n.includes(w));
};

const espnData = items[0]?.json || {};
const events   = espnData.events || [];

// Find the single event that has both requested teams as competitors
const matchedEvent = events.find(event => {
  const competitors = event.competitions?.[0]?.competitors || [];
  const names = competitors.map(c =>
    c.team?.displayName || c.team?.shortDisplayName || c.team?.name || ''
  );
  return names.some(n => matchesTeam(n, away)) &&
         names.some(n => matchesTeam(n, home));
});

return [{
  json: {
    ...espnData,
    events:      matchedEvent ? [matchedEvent] : [],
    filteredGame: matchedEvent ? (matchedEvent.name || (away + ' vs ' + home)) : null,
    gameFound:   !!matchedEvent,
    gameNote:    matchedEvent
      ? ('Matched: ' + matchedEvent.name)
      : ('Game not found in ESPN data for ' + away + ' vs ' + home),
  }
}];

const analysis = $('Bobby Vegas Analysis').item.json.message.content;
const teams = $('Parse Teams').item.json.teams;
const sport = $('Parse Teams').item.json.sport;
const now = new Date().toLocaleDateString('en-US', { 
  month: 'short', day: 'numeric', year: 'numeric' 
});

// Extract key fields from analysis
const confidenceMatch = analysis.match(/CONFIDENCE[:\s*\*]+(\w+)/i);
const confidence = confidenceMatch ? confidenceMatch[1].toUpperCase() : 'MEDIUM';

const pickMatch = analysis.match(/BOBBY'S PICK[:\s*\*]+(.*?)(?:\n|$)/i);
const bobbysPick = pickMatch ? pickMatch[1].trim() : 'See full analysis';

const edgeMatch = analysis.match(/EDGE ALERT[\s\S]*?(?=🏟️|🎯|BOBBY|$)/i);
const edgeAlert = edgeMatch ? edgeMatch[0].trim().slice(0, 300) : 'Edge analysis available in premium';

// FREE CHANNEL — teaser only, no pick revealed
const freePost = 
`⚡ **EDGE ALERT — ${now}**

Sport: ${sport}
Game: ${teams}
Confidence: **${confidence}**

${edgeAlert}

🔒 Full pick + parlay build in ⭐ **#full-picks** for Premium members.

👉 Join: whop.com/bobby-vegas

⚠️ For entertainment purposes only. Bet responsibly.`;

// PREMIUM — full analysis
const fullPost = 
`🎯 **FULL PICK — ${now}**

${analysis}

⚠️ Past results do not guarantee future performance. Bet responsibly.`;

// PREMIUM — parlay build
const parlayPost = 
`🃏 **PARLAY BUILD — ${now}**

**Anchor Leg:** ${bobbysPick}

**How To Build It:**
Leg 1: ${bobbysPick}
Leg 2: Stack with your highest confidence play today

**Sizing:** 1-2 units max
**Rule:** Only parlay when both legs show Edge Finder confirmation

⚠️ Parlays carry higher variance. Never parlay to chase losses. Bet responsibly.`;

// PREMIUM — bankroll log
const bankrollPost = 
`📊 **PICK LOGGED — ${now}**

Game: ${teams}
Pick: ${bobbysPick}
Confidence: ${confidence}
Status: ⏳ Pending result

_Result posted after game completion._`;

return [{
  json: {
    free_post: freePost,
    full_post: fullPost,
    parlay_post: parlayPost,
    bankroll_post: bankrollPost,
    teams: teams,
    confidence: confidence,
    bobby_pick: bobbysPick
  }
}];

const data = $input.first().json;
console.log('FORMAT OUTPUT KEYS:', JSON.stringify(Object.keys(data)));
console.log('free_post length:', (data.free_post || '').length);
console.log('full_post length:', (data.full_post || '').length);
console.log('parlay_post length:', (data.parlay_post || '').length);
console.log('bankroll_post length:', (data.bankroll_post || '').length);
console.log('free_post preview:', (data.free_post || '').slice(0, 80));
console.log('full_post preview:', (data.full_post || '').slice(0, 80));
return [{ json: data }];

const KALSHI_PREFIXES = ['Reg Time:', 'Total Goals:', 'Match Winner:', 'Moneyline:', 'To Win:', 'Winner:', 'Result:'];

function stripPrefix(s) {
  let clean = (s || '').trim();
  for (const prefix of KALSHI_PREFIXES) {
    const re = new RegExp('^' + prefix.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*', 'i');
    if (re.test(clean)) {
      clean = clean.replace(re, '').trim();
      break;
    }
  }
  return clean;
}

const incoming = $input.item.json;
console.log('[ValidateMatchup] RAW away_team:', incoming.away_team);
console.log('[ValidateMatchup] RAW home_team:', incoming.home_team);
console.log('[ValidateMatchup] RAW teams string:', incoming.teams);
const awayTeam = stripPrefix(incoming.away_team || '');
const homeTeam = stripPrefix(incoming.home_team || '');

const matchupValid = awayTeam.toLowerCase() !== homeTeam.toLowerCase();

return [{
  json: {
    ...incoming,
    away_team: awayTeam,
    home_team: homeTeam,
    matchup_valid: matchupValid,
  }
}];

// ===== AF Match Fixture (Code node) =====
// Input: date's fixtures from "AF Get Fixtures by Date" + parsed teams.
// Output: fixture_id, venue, team IDs for the matched game.

const normalize = s => (s || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();

const STOP = ['the','and','for','with','fc','sc','republic','herzegovina','ir','dr','pr','rep'];
const sig = name => normalize(name).split(' ').filter(w => w.length > 2 && !STOP.includes(w));

const teamMatches = (a, b) => {
  const na = normalize(a), nb = normalize(b);
  if (!na || !nb) return false;
  if (na.includes(nb) || nb.includes(na)) return true;
  const sa = sig(a), sb = sig(b);
  return sa.some(w => sb.includes(w));
};

const away = $('Parse Teams').item.json.away_team || '';
const home = $('Parse Teams').item.json.home_team || '';

let fixtures = [];
try { fixtures = $('AF Get Fixtures by Date').item.json.response || []; } catch(e) {}

let matched = null;
for (const f of fixtures) {
  const h = f.teams && f.teams.home ? f.teams.home.name : '';
  const a = f.teams && f.teams.away ? f.teams.away.name : '';
  const asIs   = teamMatches(h, home) && teamMatches(a, away);
  const flipped = teamMatches(h, away) && teamMatches(a, home);
  if (asIs || flipped) { matched = f; break; }
}

if (!matched) {
  return [{ json: {
    af_matched: false,
    fixture_id: null,
    venue_name: 'Unknown',
    venue_city: 'Unknown',
    round: 'Unknown',
    is_knockout: false,
    home_team_id: null,
    away_team_id: null,
    note: 'No API-Football fixture matched for ' + away + ' vs ' + home
  }}];
}

const fx = matched.fixture || {};
const vn = fx.venue || {};
const roundStr = (matched.league && matched.league.round) ? matched.league.round : '';
// Knockout rounds in API-Football World Cup naming: "Round of 16", "Round of 32",
// "Quarter-finals", "Semi-finals", "3rd Place Final", "Final".
// Group stage reads like "Group A" / "Group Stage - 1".
const isKnockout = /round of|quarter|semi|final|3rd place/i.test(roundStr);
return [{ json: {
  af_matched: true,
  fixture_id: fx.id != null ? fx.id : null,
  venue_name: vn.name || 'Unknown',
  venue_city: vn.city || 'Unknown',
  round: roundStr || 'Unknown',
  is_knockout: isKnockout,
  home_team_id: matched.teams && matched.teams.home ? matched.teams.home.id : null,
  away_team_id: matched.teams && matched.teams.away ? matched.teams.away.id : null,
  af_home_name: matched.teams && matched.teams.home ? matched.teams.home.name : '',
  af_away_name: matched.teams && matched.teams.away ? matched.teams.away.name : ''
}}];

// ===== AF Assemble Context (Code node) =====
// Inputs: AF Match Fixture + AF Get Injuries + AF Get Lineups +
//         AF Get Predictions + AF Get Home Squad + AF Get Away Squad
// Output: clean strings for Bobby. Rosters ALWAYS populate:
//   confirmed XI near kickoff, squad roster earlier.

const mf = $('AF Match Fixture').item.json || {};

// ----- Injuries -----
let injuriesStr = 'No injuries reported';
try {
  const inj = $('AF Get Injuries').item.json.response || [];
  if (inj.length) {
    injuriesStr = inj.map(i =>
      ((i.team && i.team.name) || '?') + ': ' + ((i.player && i.player.name) || '?') +
      ' (' + ((i.player && (i.player.reason || i.player.type)) || 'out') + ')'
    ).slice(0, 12).join('; ');
  }
} catch(e) {}

// ----- Key players: prefer confirmed XI, fall back to squad roster -----
let keyPlayersStr = '';
let lineupsFound = false;

// 1) Try confirmed/probable starting XI (available ~40 min pre-kickoff)
try {
  const lu = $('AF Get Lineups').item.json.response || [];
  if (lu.length) {
    keyPlayersStr = lu.map(t => {
      const xi = (t.startXI || [])
        .map(p => p.player && p.player.name)
        .filter(Boolean).slice(0, 11).join(', ');
      return ((t.team && t.team.name) || '?') + ' XI (' + (t.formation || '') + '): ' + xi;
    }).join(' | ');
    if (keyPlayersStr.trim()) lineupsFound = true;
  }
} catch(e) {}

// 2) Fallback: squad rosters (available anytime). Show attackers + midfielders.
if (!lineupsFound) {
  const squadNames = (nodeName) => {
    try {
      const sq = ($(nodeName).item.json.response || [])[0];
      if (!sq) return null;
      const players = sq.players || [];
      const teamName = (sq.team && sq.team.name) || '';
      const attackers = players.filter(p => p.position === 'Attacker').map(p => p.name);
      const mids      = players.filter(p => p.position === 'Midfielder').map(p => p.name);
      const picks = attackers.concat(mids).slice(0, 7);
      if (!picks.length) return null;
      return teamName + ': ' + picks.join(', ');
    } catch(e) { return null; }
  };
  const home = squadNames('AF Get Home Squad');
  const away = squadNames('AF Get Away Squad');
  const parts = [home, away].filter(Boolean);
  keyPlayersStr = parts.length
    ? parts.join(' | ') + ' (squad key names; confirmed XI posts ~40 min pre-kickoff)'
    : 'Roster data unavailable';
}

// ----- Predictions / form / h2h -----
let formStr = 'Form data unavailable';
let h2hStr = 'No recent head-to-head';
let predictionStr = 'No model prediction available';
try {
  const p = ($('AF Get Predictions').item.json.response || [])[0];
  if (p) {
    const ht = p.teams && p.teams.home, at = p.teams && p.teams.away;
    if (ht && at) {
      formStr = (ht.name || 'Home') + ' form: ' + ((ht.last_5 && ht.last_5.form) || 'n/a') +
        ' | ' + (at.name || 'Away') + ' form: ' + ((at.last_5 && at.last_5.form) || 'n/a');
    }
    if (p.predictions) {
      const pc = p.predictions.percent || {};
      predictionStr = (p.predictions.advice || 'n/a') +
        ' (Home ' + (pc.home || '?') + ' / Draw ' + (pc.draw || '?') +
        ' / Away ' + (pc.away || '?') + ')';
    }
    const h2h = p.h2h || [];
    if (h2h.length) {
      h2hStr = h2h.slice(0, 5).map(g => {
        const gh = (g.teams && g.teams.home && g.teams.home.name) || '?';
        const ga = (g.teams && g.teams.away && g.teams.away.name) || '?';
        const sh = (g.goals && g.goals.home != null) ? g.goals.home : '-';
        const sa = (g.goals && g.goals.away != null) ? g.goals.away : '-';
        return gh + ' ' + sh + '-' + sa + ' ' + ga;
      }).join('; ');
    }
  }
} catch(e) {}

return [{ json: {
  af_matched: mf.af_matched === true,
  is_knockout: mf.is_knockout === true,
  round_str: mf.round || 'Unknown',
  venue_str: (mf.venue_name || 'Unknown') + ', ' + (mf.venue_city || 'Unknown'),
  venue_city: mf.venue_city || 'Unknown',
  injuries_str: injuriesStr,
  lineups_str: keyPlayersStr,
  roster_source: lineupsFound ? 'confirmed_xi' : 'squad',
  form_str: formStr,
  h2h_str: h2hStr,
  prediction_str: predictionStr
}}];

const game = $input.first().json;

// Enrich search context from AF Assemble Context and Webhook body
// so rules fire even when Match Kalshi Teams output has limited fields
let afCtx = {};
try { afCtx = $('AF Assemble Context').first().json || {}; } catch(e) {}
let wh = {};
try { wh = $('Webhook').first().json?.body ?? $('Webhook').first().json ?? {}; } catch(e) {}

// Build one comprehensive lowercase search string from all sources
const searchStr = [
  JSON.stringify(game),
  JSON.stringify(afCtx),
  JSON.stringify(wh)
].join(' ').toLowerCase();

const contextRules = [];

// Rule 1: World Cup 3rd Place Game — Fade the Draw
const isWorldCup =
  searchStr.includes('world cup') ||
  searchStr.includes('worldcup') ||
  searchStr.includes('fifa') ||
  searchStr.includes('kxwc');  // Kalshi World Cup ticker prefix

const is3rdPlace =
  searchStr.includes('third') ||
  searchStr.includes('3rd place') ||
  searchStr.includes('bronze') ||
  searchStr.includes('third place');

if (isWorldCup && is3rdPlace) {
  contextRules.push({
    rule: "WORLD_CUP_3RD_PLACE_DRAW_FADE",
    confidence: "HIGH",
    context: "HISTORICAL EDGE: Zero World Cup 3rd place games have ended goalless in regulation across 20+ tournaments since 1934. Draw probability is structurally overpriced. Sportsbooks price draw at ~24% implied — actual historical frequency is ~0%. 4 of last 7 games had 4+ goals. Both teams play to win — no tactical incentive to draw.",
    market_implications: "FADE THE DRAW. Consider Over 3.5 at +EV pricing. Lean France ML or either team to win. Avoid draw/tie market entirely.",
    edge_strength: "MAXIMUM — historical frequency contradicts current market pricing"
  });
}

// Rule 2: World Cup Asian Handicap Kalshi Divergence
if (isWorldCup && game.kalshi_divergence > 5) {
  contextRules.push({
    rule: "WORLD_CUP_AH_KALSHI_DIVERGENCE",
    confidence: "HIGH",
    context: "Bobby Vegas documented 26-0 peak streak using Asian Handicap -1.5 Kalshi divergence signal during 2026 World Cup. Divergence >5% is highest confidence signal in the system.",
    market_implications: "Activate full Sharp Protocol on Asian Handicap -1.5 line.",
    edge_strength: "PROVEN — 26-0 documented record"
  });
}

// Rule 3: WNBA Back-to-Back Fatigue
const isWNBA = searchStr.includes('wnba');
const hasB2B = game.home_b2b === true || game.away_b2b === true ||
               searchStr.includes('back to back') ||
               searchStr.includes('back-to-back');

if (isWNBA && hasB2B) {
  contextRules.push({
    rule: "WNBA_B2B_FATIGUE_FADE",
    confidence: "MEDIUM",
    context: "Back-to-back games in WNBA create meaningful fatigue edge. B2B team loses cover at elevated rate. Line typically underadjusts for fatigue.",
    market_implications: "Fade the B2B team. Lean opponent moneyline or spread.",
    edge_strength: "DOCUMENTED — Portland Fire +210 win with this signal"
  });
}

// Rule 4: MLB High Total Lean
const isMLB = searchStr.includes('mlb') || searchStr.includes('baseball');
const highTotal = (game.total > 9.5) || (game.over_under > 9.5);

if (isMLB && highTotal) {
  contextRules.push({
    rule: "MLB_HIGH_TOTAL_OVER_LEAN",
    confidence: "MEDIUM",
    context: "Total set above 9.5 suggests vulnerable pitching or favorable conditions. Historical over rate elevated at this line.",
    market_implications: "Consider Over. Check weather, wind direction, ballpark factors before confirming.",
    edge_strength: "MEDIUM — check conditions before activating"
  });
}

const output = {
  ...game,
  historical_context: contextRules,
  context_count: contextRules.length,
  has_historical_edge: contextRules.length > 0,
  active_rules: contextRules.map(r => r.rule)
};

return [{ json: output }];

const now  = new Date();
const fmt  = d => d.toISOString().replace(/-/g, '').slice(0, 8);
const from = fmt(now);
const to   = fmt(new Date(now.getTime() + 3 * 86400 * 1000));

const url = 'https://site.api.espn.com/apis/site/v2/sports/soccer/fifa.world/scoreboard?dates=' + from + '-' + to;

try {
  const data = await $helpers.httpRequest({ url, method: 'GET' });
  return [{ json: data }];
} catch (e) {
  return [{ json: { events: [], fetchError: e.message, url } }];
}

